begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
insert into auth.users (id) values ('71000000-0000-4000-8000-000000000001'), ('71000000-0000-4000-8000-000000000002'), ('71000000-0000-4000-8000-000000000003');
insert into organizations (id, name) values ('72000000-0000-4000-8000-000000000001', 'A'), ('72000000-0000-4000-8000-000000000002', 'B');
insert into establishments (id, organization_id, name, timezone) values ('73000000-0000-4000-8000-000000000001', '72000000-0000-4000-8000-000000000001', 'A1', 'UTC'), ('73000000-0000-4000-8000-000000000002', '72000000-0000-4000-8000-000000000001', 'A2', 'UTC'), ('73000000-0000-4000-8000-000000000003', '72000000-0000-4000-8000-000000000002', 'B1', 'UTC');
insert into memberships (organization_id, user_id, role) values ('72000000-0000-4000-8000-000000000001', '71000000-0000-4000-8000-000000000001', 'owner'), ('72000000-0000-4000-8000-000000000002', '71000000-0000-4000-8000-000000000002', 'owner'), ('72000000-0000-4000-8000-000000000001', '71000000-0000-4000-8000-000000000003', 'member');
insert into suppliers (organization_id,establishment_id,name,email,contact) values ('72000000-0000-4000-8000-000000000002', '73000000-0000-4000-8000-000000000003','Externo','externo@example.test','999');
set local role authenticated;
select set_config('request.jwt.claims', '{"sub":"71000000-0000-4000-8000-000000000001","role":"authenticated"}', true);
select lives_ok($$insert into suppliers (organization_id,establishment_id,name,email,contact) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Horta','compras@example.test','+55 (51) 0011-2233')$$, 'proprietário registra contatos');
select is((select email from suppliers where name='Horta'),'compras@example.test','e-mail persistido');
select is((select contact from suppliers where name='Horta'),'+55 (51) 0011-2233','contato preserva formatação');
select is((select count(*) from suppliers where email='externo@example.test'),0::bigint,'contatos de B não são lidos por A');
select lives_ok($$insert into suppliers (organization_id,establishment_id,name) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Legado')$$, 'nome sozinho continua aceito');
select ok((select email is null and contact is null from suppliers where name='Legado'),'opcionais omitidos são nulos');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,email) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Inválido','inválido')$$,'23514',null,'recusa email inválido');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,email) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Inválido',' a@example.test')$$,'23514',null,'recusa email com borda');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,email) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Inválido',repeat('a',243)||'@example.test')$$,'23514',null,'recusa email longo');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,contact) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Inválido','')$$,'23514',null,'recusa contato vazio');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,contact) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Inválido',repeat('x',81))$$,'23514',null,'recusa contato longo');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,contact) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Inválido',U&'\00A0telefone')$$,'23514',null,'recusa contato com borda unicode');
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,email) values ('72000000-0000-4000-8000-000000000002', '73000000-0000-4000-8000-000000000003','Ataque','a@example.test')$$,'42501',null,'A não insere contato em B');
select throws_ok($$update suppliers set contact='999'$$,'42501',null,'edição continua negada');
select throws_ok($$insert into suppliers (id,organization_id,establishment_id,name) values (gen_random_uuid(),'72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Id')$$,'42501',null,'id continua protegido');
select set_config('request.jwt.claims', '{"sub":"71000000-0000-4000-8000-000000000003","role":"authenticated"}', true);
select throws_ok($$insert into suppliers (organization_id,establishment_id,name,email,contact) values ('72000000-0000-4000-8000-000000000001', '73000000-0000-4000-8000-000000000001','Membro','a@example.test','999')$$,'42501',null,'colaborador não cadastra contatos');
set local role anon;
select throws_ok($$select email,contact from suppliers$$,'42501',null,'anônimo não lê contatos');
select * from finish();
rollback;
